<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body {
            background-color: #303030;
            color: #d4d4d4;
            font-family: sans-serif;
            margin: 0;
