            border: 1px solid #444;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        .fs-item {
            padding: 5px;
            cursor: pointer;
        }

        #files-path {
            font-weight: bold;
            margin: 0;
        }

        #tabs {
            display: flex;
            border-bottom: 1px solid #444;
