</head>
<body>
<div id="desktop">
    <div id="taskbar">
        <button id="open-files">Files</button>
        <button id="open-notepad">Notepad</button>
    </div>
    <div id="files-content">
        <div id="files-path">/</div>
        <div class="fs-item" onclick="navigate('/bin')">bin</div>
        <div class="fs-item" onclick="navigate('/etc')">etc</div>
        <div class="fs-item" onclick="navigate('/home')">home</div>
        <div class="fs-item" onclick="navigate('/usr')">usr</div>
        <div class="fs-item" onclick="navigate('/var')">var</div>
        <div class="fs-item" onclick="navigate('/home/user')">
            <div class="fs-item" onclick="navigate('/home/user/Documents')">Documents</div>
            <div class="fs-item" onclick="navigate('/home/user/Downloads')">Downloads</div>
            <div class="fs-item" onclick="navigate('/home/user/Pictures')">Pictures</div>
        </div>
    </div>

    <div id="files-up" onclick="goUp()">..</div>

    <div id="notepad-content">
        <div id="tabs">
            <button class="tab active" onclick="setActiveTab(0)">Tab 1</button>
            <button class="tab" onclick="setActiveTab(1)">Tab 2</button>
            <button class="tab" onclick="newTab()">New Tab</button>
        </div>
        <div id="editor" contenteditable="true"></div>
    </div>
</div>

<script>
    let currentPath = '/';
    const filesContent = document.getElementById('files-content');
    const filesPathDisplay = document.getElementById('files-path');
    const filesUpButton = document.getElementById('files-up');
    const notepadContent = document.getElementById('notepad-content');
    const tabs = document.querySelectorAll('.tab');
    const editor = document.getElementById('editor');
    let activeTab = 0;

    function navigate(path) {
        currentPath = path;
        filesPathDisplay.textContent = currentPath;
        if (currentPath === '/') {
            filesContent.innerHTML = '<div>bin</div><div>etc</div><div>home</div><div>usr</div><div>var</div>';
        } else if (currentPath.startsWith('/home/user')) {
            filesContent.innerHTML = `
                <div class="fs-item" onclick="navigate('/home/user/Documents')">Documents</div>
                <div class="fs-item" onclick="navigate('/home/user/Downloads')">Downloads</div>
                <div class="fs-item" onclick="navigate('/home/user/Pictures')">Pictures</div>`;
        } else {
            filesContent.innerHTML = ''; // Or a placeholder for other directories
        }
    }

    function goUp() {
        if (currentPath === '/') {
            return;
        }
        const parts = currentPath.split('/');
        if (parts.length > 1) {
            const parentPath = '/' + parts.slice(0, -1).join('/');
            navigate(parentPath);
        }
    }

    function setActiveTab(index) {
        tabs.forEach((tab, i) => tab.classList.remove('active'));
        tabs[index].classList.add('active');
        editor.innerHTML = localStorage.getItem(`tab-${index}`) || '';
    }

    function newTab() {
        const newTabButton = document.createElement('button');
        newTabButton.className = 'tab';
        newTabButton.onclick = () => setActiveTab(tabs.length);
        newTabButton.textContent = `Tab ${tabs.length + 1}`;
        tabs.forEach((tab, i) => tab.parentNode.insertBefore(newTabButton, tab.nextSibling));

        localStorage.setItem(`tab-${tabs.length}`, editor.innerHTML);
    }
</script>
</body>
</html>
